import Foundation

// Bundled list of the DB stations across Germany with the FaSta equipment
// numbers of their elevators (Shared/Resources/national-stations.json,
// generated by scripts/generate-national-stations.py from the Aufzugsstatus
// API — plötzlich querschnitt, CC BY 4.0). transit.accessibility.cloud
// carries these ~2500 DB elevators with status and (mostly) a centroid, but
// without a station; this list is what names them (EquipmentCatalog.overlaid
// → nationalNamed), so DB stations beyond the VBB are searchable offline,
// favoritable under their numeric accessibility.cloud id and refreshed in
// the one favorites batch. The Aufzugsstatus API itself then only answers
// for the city operators and for DB stations this list doesn't know yet.
// Bundled into the iOS app, the widget extension and the watch app; the
// watch widget extension keeps a membership exception (it needs no search).
nonisolated enum NationalStations {
    struct Station: Decodable, Equatable {
        // DB station number — Equipment.stationId for the records it names.
        let stationNumber: Int
        let name: String
        // Mean of the elevators' coordinates; absent for a station none of
        // whose lifts the API places.
        let latitude: Double?
        let longitude: Double?
        // FaSta equipment numbers = accessibility.cloud's
        // linked_data.operator_inventory_id.
        let lifts: [Int]
    }

    static let stations: [Station] = load()

    private struct File: Decodable {
        let stations: [Station]
    }

    // Pure parsing, unit-tested; `load()` only adds the bundle lookup.
    static func parse(_ data: Data) -> [Station] {
        (try? JSONDecoder().decode(File.self, from: data))?.stations ?? []
    }

    // Station per FaSta number, keyed as the inventory id string the live
    // records carry. First station wins should a number ever appear twice.
    static func byLift(_ stations: [Station]) -> [String: Station] {
        Dictionary(
            stations.flatMap { station in station.lifts.map { (String($0), station) } },
            uniquingKeysWith: { first, _ in first }
        )
    }

    private static func load() -> [Station] {
        guard let url = Bundle.main.url(forResource: "national-stations", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return [] }
        return parse(data)
    }
}
